89	fn tarball_tmp_entries(dir: &Path) -> Vec<String> {
90	    let mut entries = dir
91	        .read_dir()
92	        .map(|entries| {
93	            entries
94	                .filter_map(Result::ok)
95	                .filter_map(|entry| {
96	                    let name = entry.file_name().to_string_lossy().into_owned();
97	                    name.starts_with("foo-1.0.0.tgz.tmp.").then_some(name)
98	                })
99	                .collect::<Vec<_>>()
100	        })
101	        .unwrap_or_default();
102	    entries.sort();
103	    entries
104	}
105	
106	async fn await_nonempty_tarball_tmp(dir: &Path) -> Vec<String> {
107	    let deadline = std::time::Instant::now() + Duration::from_secs(2);
108	    loop {
109	        let entries = tarball_tmp_entries(dir);
110	        if entries
111	            .iter()
112	            .any(|name| std::fs::metadata(dir.join(name)).is_ok_and(|metadata| metadata.len() > 0))
113	        {
114	            return entries;
115	        }
116	        assert!(std::time::Instant::now() < deadline, "tarball body was not written to tmp");
117	        tokio::time::sleep(Duration::from_millis(20)).await;
118	    }
119	}
