137	        drop(self.file.take());
138	        let Some(tmp_path) = self.tmp_path.take() else { return };
139	        match std::fs::remove_file(&tmp_path) {
140	            Ok(()) => {}
141	            Err(err) if err.kind() == ErrorKind::NotFound => {}
142	            Err(err) => {
143	                tracing::warn!(?err, path = %tmp_path.display(), "tarball cache temp cleanup failed");
144	            }
