/// Carrier for [`stream_verified_to_cache`]'s tee. `write` stays `Some` for
/// the life of the stream so any early drop (client disconnect, error) runs
/// [`TarballWrite`]'s temp-file cleanup; it is only taken to promote the
/// verified bytes at end-of-stream.
struct TeeToCache {
    upstream: Pin<Box<dyn Stream<Item = reqwest::Result<Bytes>> + Send>>,
    write: Option<TarballWrite>,
    checker: IntegrityChecker,
    written: u64,
    max_bytes: u64,
}

