+/// Tee an upstream tarball response to the client while hashing it into
+/// `write`'s temp file, promoting the temp file to the cache only after the
+/// complete body passes `integrity` at end-of-stream.
+///
+/// The declared `Content-Length` is checked up front: an oversized response
+/// returns [`TarballStreamError::TooLarge`] synchronously — before the status
+/// line is sent — and dropping `write` removes the temp file. Otherwise the
+/// status line is already committed by the time bytes flow, so downstream
+/// failures surface *in the body*, not as a status:
+///
+/// * An SRI mismatch still streams every received byte to the client (the
+///   install client re-verifies on receipt); the temp file is simply never
+///   promoted.
+/// * An upstream transport error or truncation surfaces as an error on the
+///   response body and the temp file is never promoted.
+/// * A client disconnect drops the body mid-stream, which drops `write` and
+///   removes the temp file through its [`Drop`] impl.
+pub fn stream_verified_to_cache(
+    response: reqwest::Response,
+    write: TarballWrite,
+    integrity: &Integrity,
+    max_bytes: u64,
+) -> Result<Body, TarballStreamError> {
+    if let Some(received) = response.content_length()
+        && received > max_bytes
+    {
+        // `write` is dropped here; its `Drop` removes the temp file before any
+        // status line or byte reaches the client.
+        return Err(TarballStreamError::TooLarge { limit: max_bytes, received });
+    }
+    let checker = integrity_checker(integrity).map_err(TarballStreamError::Integrity)?;
+    let state = TeeToCache {
+        upstream: Box::pin(response.bytes_stream()),
+        write: Some(write),
+        checker,
+        written: 0,
+        max_bytes,
+    };
+    let stream = stream::unfold(Some(state), |maybe_state| async move {
+        let mut state = maybe_state?;
+        match state.upstream.next().await {
+            Some(Ok(chunk)) => {
+                let received = state.written.saturating_add(chunk.len() as u64);
+                if received > state.max_bytes {
+                    // `state` (holding `write`) drops after this yield, removing
+                    // the temp file; the terminal `None` ends the stream.
+                    return Some((
+                        Err(io::Error::other(format!(
+                            "tarball body exceeds {} byte limit (received {received} bytes)",
+                            state.max_bytes,
+                        ))),
+                        None,
+                    ));
+                }
+                if let Some(write) = state.write.as_mut()
+                    && let Err(err) = write.write_all(&chunk).await
+                {
+                    return Some((Err(err), None));
+                }
+                state.checker.input(&chunk);
+                state.written = received;
+                Some((Ok(chunk), Some(state)))
+            }
+            // Upstream error/truncation: surface at the body level and abandon
+            // the temp file (dropped with `state`).
+            Some(Err(source)) => Some((Err(io::Error::other(source)), None)),
+            None => {
+                let TeeToCache { write, checker, .. } = state;
+                // On a match, promote the verified bytes; on a mismatch, let
+                // `write` drop to remove the temp file. Either way the body has
+                // already ended cleanly for the client.
+                if checker.result().is_ok()
+                    && let Some(write) = write
+                    && let Err(err) = write.finalize().await
+                {
+                    tracing::warn!(?err, "verified tarball cache promotion failed");
+                }
+                None
+            }
+        }
+    });
+    Ok(Body::from_stream(stream))
+}
+
+/// Carrier for [`stream_verified_to_cache`]'s tee. `write` stays `Some` for
+/// the life of the stream so any early drop (client disconnect, error) runs
+/// [`TarballWrite`]'s temp-file cleanup; it is only taken to promote the
+/// verified bytes at end-of-stream.
+struct TeeToCache {
+    upstream: Pin<Box<dyn Stream<Item = reqwest::Result<Bytes>> + Send>>,
+    write: Option<TarballWrite>,
+    checker: IntegrityChecker,
+    written: u64,
+    max_bytes: u64,
+}
